-- --- hand-written ------------------------------------------------------------------------------------------

ALTER TABLE asset_categories
  ADD CONSTRAINT ck_asset_categories__code CHECK (code ~ '^[a-z0-9][a-z0-9_-]{0,39}$'),
  ADD CONSTRAINT ck_asset_categories__life CHECK (useful_life_months BETWEEN 1 AND 1200);
CREATE TRIGGER tg_asset_categories__no_delete BEFORE DELETE ON asset_categories
  FOR EACH ROW EXECUTE FUNCTION tg_forbid_delete();

ALTER TABLE fixed_assets
  ADD CONSTRAINT ck_fixed_assets__asset_no CHECK (btrim(asset_no) <> '' AND btrim(name) <> ''),
  ADD CONSTRAINT ck_fixed_assets__amounts CHECK (
    cost > 0 AND residual_value >= 0 AND residual_value < cost
    AND accumulated_depreciation >= 0 AND accumulated_depreciation <= cost - residual_value),
  ADD CONSTRAINT ck_fixed_assets__life CHECK (useful_life_months BETWEEN 1 AND 1200),
  ADD CONSTRAINT ck_fixed_assets__start CHECK (EXTRACT(DAY FROM depreciation_start_on) = 1 AND depreciation_start_on >= date_trunc('month', acquired_on)::date),
  -- From a vendor bill (capitalised by the bill, P25) or manual with the account credited (FA01).
  ADD CONSTRAINT ck_fixed_assets__source CHECK (
    (source = 'vendor_bill') = (vendor_invoice_id IS NOT NULL) AND (source = 'manual') = (credit_account_id IS NOT NULL)),
  ADD CONSTRAINT ck_fixed_assets__disposal CHECK (
    (status IN ('disposed', 'written_off')) = (disposed_on IS NOT NULL)
    AND (disposed_on IS NULL OR (disposal_proceeds IS NOT NULL AND btrim(coalesce(disposal_reason, '')) <> '' AND disposed_on >= acquired_on))
    AND (disposal_proceeds IS NULL OR disposal_proceeds >= 0)
    AND (status <> 'written_off' OR disposal_proceeds = 0)
    AND (coalesce(disposal_proceeds, 0) = 0 OR proceeds_account_id IS NOT NULL)),
  ADD CONSTRAINT ck_fixed_assets__fully CHECK (status <> 'fully_depreciated' OR accumulated_depreciation = cost - residual_value);

-- The registration snapshot never changes; a disposed or written-off asset is final.
CREATE FUNCTION tg_fixed_assets__frozen() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF OLD.status IN ('disposed', 'written_off') THEN
    RAISE EXCEPTION 'a disposed asset is final' USING ERRCODE = 'restrict_violation';
  END IF;
  IF NEW.entity_id IS DISTINCT FROM OLD.entity_id OR NEW.asset_no IS DISTINCT FROM OLD.asset_no
    OR NEW.category_id IS DISTINCT FROM OLD.category_id OR NEW.source IS DISTINCT FROM OLD.source
    OR NEW.acquired_on IS DISTINCT FROM OLD.acquired_on OR NEW.depreciation_start_on IS DISTINCT FROM OLD.depreciation_start_on
    OR NEW.cost IS DISTINCT FROM OLD.cost OR NEW.residual_value IS DISTINCT FROM OLD.residual_value
    OR NEW.useful_life_months IS DISTINCT FROM OLD.useful_life_months OR NEW.method IS DISTINCT FROM OLD.method
    OR NEW.asset_account_id IS DISTINCT FROM OLD.asset_account_id OR NEW.accumulated_account_id IS DISTINCT FROM OLD.accumulated_account_id
    OR NEW.expense_account_id IS DISTINCT FROM OLD.expense_account_id
    OR NEW.disposal_gain_loss_account_id IS DISTINCT FROM OLD.disposal_gain_loss_account_id
    OR NEW.vendor_invoice_id IS DISTINCT FROM OLD.vendor_invoice_id OR NEW.credit_account_id IS DISTINCT FROM OLD.credit_account_id
    OR NEW.accumulated_depreciation < OLD.accumulated_depreciation THEN
    RAISE EXCEPTION 'an asset keeps its registration' USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER tg_fixed_assets__frozen BEFORE UPDATE ON fixed_assets
  FOR EACH ROW EXECUTE FUNCTION tg_fixed_assets__frozen();
CREATE TRIGGER tg_fixed_assets__no_delete BEFORE DELETE ON fixed_assets
  FOR EACH ROW EXECUTE FUNCTION tg_forbid_delete();

ALTER TABLE depreciation_runs
  ADD CONSTRAINT ck_depreciation_runs__amounts CHECK (total_amount >= 0 AND asset_count >= 0);
CREATE TRIGGER tg_depreciation_runs__append_only BEFORE UPDATE OR DELETE ON depreciation_runs
  FOR EACH ROW EXECUTE FUNCTION forbid_mutation();

ALTER TABLE depreciation_lines
  ADD CONSTRAINT ck_depreciation_lines__amounts CHECK (amount > 0 AND accumulated_after >= amount);
CREATE TRIGGER tg_depreciation_lines__append_only BEFORE UPDATE OR DELETE ON depreciation_lines
  FOR EACH ROW EXECUTE FUNCTION forbid_mutation();
